from __future__ import annotations

from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    file_path = Path(path)
    text = file_path.read_text()
    if old not in text:
        raise RuntimeError(f"expected source block not found in {path}: {old[:120]!r}")
    file_path.write_text(text.replace(old, new, 1))


# 1. Native MarketDataManager transport-vs-symbol failure classification.
mdm = "src/nifty_scalper_bot/data/market_data_manager.py"
replace_once(
    mdm,
    '''        transport_failure = not processing_backlog and (\n            heartbeat_stale\n            or (spot_stale and fut_stale)\n            or stale_ratio >= 0.70\n            or subscription_transport_failure\n        )\n''',
    '''        # A broad set of stale symbols is not, by itself, proof that the\n        # WebSocket transport failed. A healthy socket can continue receiving\n        # heartbeats while one subscription generation is incomplete. Global\n        # reconnects are therefore reserved for explicit transport evidence.\n        transport_failure = bool(stale_or_missing_symbols) and not processing_backlog and (\n            heartbeat_stale\n            or not ws_healthy\n            or subscription_transport_failure\n        )\n''',
)

replace_once(
    mdm,
    '''        if stale_or_missing_symbols and not transport_failure:\n            for sym in stale_or_missing_symbols:\n                age = self.time_since_last_live_ws_tick(sym)\n                self.request_fallback_refresh(sym, reason="ws_symbol_stale_recovery")\n                self._last_symbol_level_recovery_mono = now_mono\n                self._logger.warning(\n                    "WS_SYMBOL_STALE_RECOVERY symbol=%s required=%s stale_age_s=%s heartbeat_age_s=%s reason=%s",\n                    sym,\n                    sym in required,\n                    age,\n                    heartbeat_age,\n                    (\n                        "missing_first_ws_tick"\n                        if sym in missing_symbols\n                        else "stale_ws_tick"\n                    ),\n                    extra={\n                        "event": "WS_SYMBOL_STALE_RECOVERY",\n                        "symbol": sym,\n                        "required": sym in required,\n                        "stale_age_s": age,\n                        "heartbeat_age_s": heartbeat_age,\n                        "ws_healthy": ws_healthy,\n                        "subscription_divergence": subscription_divergence,\n                        "subscription_divergence_age_s": divergence_age,\n                        "reason": (\n                            "missing_first_ws_tick"\n                            if sym in missing_symbols\n                            else "stale_ws_tick"\n                        ),\n                    },\n                )\n            self._logger.warning(\n                "WS_GLOBAL_RESTART_SUPPRESSED stale_symbols=%d heartbeat_age_s=%s reason=no_transport_failure",\n                len(stale_symbols),\n                heartbeat_age,\n                extra={\n                    "event": "WS_GLOBAL_RESTART_SUPPRESSED",\n                    "stale_symbols": stale_symbols,\n                    "missing_symbols": missing_symbols,\n                    "heartbeat_age_s": heartbeat_age,\n                    "ws_healthy": ws_healthy,\n                    "subscription_divergence": subscription_divergence,\n                    "subscription_divergence_age_s": divergence_age,\n                    "reason": "no_transport_failure",\n                },\n            )\n            self._zombie_stale_logged = False\n            return\n''',
    '''        if stale_or_missing_symbols and not transport_failure:\n            recovery_last = getattr(self, "_symbol_recovery_last_attempt_mono", None)\n            if not isinstance(recovery_last, dict):\n                recovery_last = {}\n                self._symbol_recovery_last_attempt_mono = recovery_last\n            recovery_cooldown_s = max(\n                float(getattr(self, "_symbol_recovery_cooldown_s", 5.0) or 5.0),\n                1.0,\n            )\n            dispatched_symbols: list[str] = []\n            for sym in stale_or_missing_symbols:\n                last_attempt = float(recovery_last.get(sym, 0.0) or 0.0)\n                if now_mono - last_attempt < recovery_cooldown_s:\n                    continue\n                recovery_last[sym] = now_mono\n                age = self.time_since_last_live_ws_tick(sym)\n                dispatched = self.request_fallback_refresh(\n                    sym, reason="ws_symbol_stale_recovery"\n                )\n                if not dispatched:\n                    continue\n                dispatched_symbols.append(sym)\n                self._last_symbol_level_recovery_mono = now_mono\n                self._logger.warning(\n                    "WS_SYMBOL_STALE_RECOVERY symbol=%s required=%s stale_age_s=%s heartbeat_age_s=%s reason=%s",\n                    sym,\n                    sym in required,\n                    age,\n                    heartbeat_age,\n                    (\n                        "missing_first_ws_tick"\n                        if sym in missing_symbols\n                        else "stale_ws_tick"\n                    ),\n                    extra={\n                        "event": "WS_SYMBOL_STALE_RECOVERY",\n                        "symbol": sym,\n                        "required": sym in required,\n                        "stale_age_s": age,\n                        "heartbeat_age_s": heartbeat_age,\n                        "ws_healthy": ws_healthy,\n                        "subscription_divergence": subscription_divergence,\n                        "subscription_divergence_age_s": divergence_age,\n                        "reason": (\n                            "missing_first_ws_tick"\n                            if sym in missing_symbols\n                            else "stale_ws_tick"\n                        ),\n                    },\n                )\n            log_throttled(\n                self._logger,\n                "ws_global_restart_suppressed_symbol_recovery",\n                "WS_GLOBAL_RESTART_SUPPRESSED stale_symbols=%d missing_symbols=%d heartbeat_age_s=%s reason=symbol_level_recovery"\n                % (len(stale_symbols), len(missing_symbols), heartbeat_age),\n                interval_sec=30.0,\n                level=logging.WARNING,\n                extra={\n                    "event": "WS_GLOBAL_RESTART_SUPPRESSED",\n                    "stale_symbols": stale_symbols,\n                    "missing_symbols": missing_symbols,\n                    "recovery_dispatched_symbols": dispatched_symbols,\n                    "heartbeat_age_s": heartbeat_age,\n                    "ws_healthy": ws_healthy,\n                    "subscription_divergence": subscription_divergence,\n                    "subscription_divergence_age_s": divergence_age,\n                    "reason": "symbol_level_recovery",\n                },\n            )\n            self._zombie_stale_logged = False\n            return\n''',
)

replace_once(
    mdm,
    '''        return {\n            "trading_feed_healthy": futures_fresh and options_fresh,\n            "futures_fresh": futures_fresh,\n            "options_fresh": options_fresh,\n            "spot_fresh": spot_fresh,\n            "spot_symbol": spot_symbol,\n            "spot_age_ms": self.symbol_data_age_ms(spot_symbol),\n            "futures_symbol": futures_symbol,\n            "futures_age_ms": (\n                self.symbol_data_age_ms(futures_symbol)\n                if futures_symbol\n                else 1_000_000_000\n            ),\n            "option_symbols": option_symbols,\n            "threshold_ms": threshold,\n        }\n''',
    '''        required_symbols = sorted(self._required_live_symbols())\n        stale_required_symbols: list[str] = []\n        required_symbol_readiness: dict[str, dict[str, Any]] = {}\n        for symbol in required_symbols:\n            token = self.current_live_token(symbol)\n            readiness = self.classify_live_tick_readiness(\n                symbol, token, max_age_s=max(float(threshold) / 1000.0, 0.001)\n            )\n            required_symbol_readiness[symbol] = readiness\n            if not bool(readiness.get("ready")):\n                stale_required_symbols.append(symbol)\n        recovery_active = bool(stale_required_symbols)\n        return {\n            "trading_feed_healthy": futures_fresh and options_fresh and not recovery_active,\n            "futures_fresh": futures_fresh,\n            "options_fresh": options_fresh,\n            "spot_fresh": spot_fresh,\n            "spot_symbol": spot_symbol,\n            "spot_age_ms": self.symbol_data_age_ms(spot_symbol),\n            "futures_symbol": futures_symbol,\n            "futures_age_ms": (\n                self.symbol_data_age_ms(futures_symbol)\n                if futures_symbol\n                else 1_000_000_000\n            ),\n            "option_symbols": option_symbols,\n            "threshold_ms": threshold,\n            "required_symbols": required_symbols,\n            "stale_required_symbols": stale_required_symbols,\n            "required_symbol_recovery_active": recovery_active,\n            "required_symbol_readiness": required_symbol_readiness,\n        }\n''',
)

# 2. Correct polling supervisor installation identity check.
polling_runtime = "src/nifty_scalper_bot/core/polling_failover_runtime.py"
replace_once(
    polling_runtime,
    '''    degraded = getattr(app_module, "_polling_fallback_degraded", None)\n    supervisor = getattr(app_module, "_polling_failover_supervisor_iteration", None)\n    try:\n        degraded_params = inspect.signature(degraded).parameters if callable(degraded) else {}\n    except (TypeError, ValueError):\n        degraded_params = {}\n    if callable(supervisor) and "quote_stale_ms" in degraded_params:\n        setattr(app_module, _PATCH_ATTR, True)\n        return True\n''',
    '''    supervisor = getattr(app_module, "_polling_failover_supervisor_iteration", None)\n    if callable(supervisor) and getattr(\n        supervisor, "_nifty_polling_supervisor_version", None\n    ) == 2:\n        setattr(app_module, _PATCH_ATTR, True)\n        return False\n''',
)
replace_once(
    polling_runtime,
    '''    setattr(app_module, "_polling_fallback_degraded", _polling_fallback_degraded)\n    setattr(\n        app_module,\n        "_polling_failover_supervisor_iteration",\n        _installed_polling_failover_supervisor_iteration,\n    )\n''',
    '''    setattr(\n        _installed_polling_failover_supervisor_iteration,\n        "_nifty_polling_supervisor_version",\n        2,\n    )\n    setattr(app_module, "_polling_fallback_degraded", _polling_fallback_degraded)\n    setattr(\n        app_module,\n        "_polling_failover_supervisor_iteration",\n        _installed_polling_failover_supervisor_iteration,\n    )\n''',
)

# 3. Regression tests: healthy transport must recover symbols, never globally restart.
test_path = "tests/data/test_mdm_tick_coalescing.py"
replace_once(
    test_path,
    '''def test_spot_and_futures_both_stale_may_trigger_full_restart(monkeypatch):\n    from nifty_scalper_bot.utils import market_hours\n\n    mdm = MarketDataManager(kite=None)\n    _wire_symbols(mdm)\n    now = time.monotonic()\n    required = mdm._required_live_symbols()\n    mdm._symbols_with_tick.update(required)\n    for sym in required:\n        mdm._last_valid_live_tick_mono[sym] = now\n    mdm._last_valid_live_tick_mono["NSE:NIFTY"] = now - 120.0\n    mdm._last_valid_live_tick_mono["NFO:NIFTY26JUNFUT"] = now - 120.0\n    mdm._zombie_tick_threshold_sec = 60.0\n    mdm._last_hb_mono = now\n    restarted = []\n    monkeypatch.setattr(market_hours, "is_market_open", lambda: True)\n    monkeypatch.setattr(mdm, "_is_ws_healthy", lambda: True)\n    monkeypatch.setattr(mdm, "_monitor_spot_ws_health", lambda: None)\n    monkeypatch.setattr(\n        mdm, "_trigger_zombie_ws_restart", lambda: restarted.append(True)\n    )\n\n    mdm._check_zombie_ticks()\n\n    assert restarted == [True]\n''',
    '''def test_spot_and_futures_stale_use_symbol_recovery_when_transport_healthy(monkeypatch):\n    from nifty_scalper_bot.utils import market_hours\n\n    mdm = MarketDataManager(kite=None)\n    _wire_symbols(mdm)\n    now = time.monotonic()\n    required = mdm._required_live_symbols()\n    mdm._symbols_with_tick.update(required)\n    for sym in required:\n        mdm._last_valid_live_tick_mono[sym] = now\n    mdm._last_valid_live_tick_mono["NSE:NIFTY"] = now - 120.0\n    mdm._last_valid_live_tick_mono["NFO:NIFTY26JUNFUT"] = now - 120.0\n    mdm._zombie_tick_threshold_sec = 60.0\n    mdm._last_hb_mono = now\n    rest_requests: list[tuple[str, str]] = []\n    monkeypatch.setattr(market_hours, "is_market_open", lambda: True)\n    monkeypatch.setattr(mdm, "_is_ws_healthy", lambda: True)\n    monkeypatch.setattr(mdm, "_monitor_spot_ws_health", lambda: None)\n    monkeypatch.setattr(\n        mdm,\n        "request_fallback_refresh",\n        lambda symbol, reason: rest_requests.append((symbol, reason)) or True,\n    )\n    monkeypatch.setattr(\n        mdm,\n        "_trigger_zombie_ws_restart",\n        lambda: pytest.fail("healthy transport must not restart globally"),\n    )\n\n    mdm._check_zombie_ticks()\n\n    assert {symbol for symbol, _ in rest_requests} == {\n        "NSE:NIFTY",\n        "NFO:NIFTY26JUNFUT",\n    }\n\n\ndef test_heartbeat_stale_triggers_single_global_restart(monkeypatch):\n    from nifty_scalper_bot.utils import market_hours\n\n    mdm = MarketDataManager(kite=None)\n    _wire_symbols(mdm)\n    now = time.monotonic()\n    required = mdm._required_live_symbols()\n    mdm._symbols_with_tick.update(required)\n    for sym in required:\n        mdm._last_valid_live_tick_mono[sym] = now - 120.0\n    mdm._zombie_tick_threshold_sec = 60.0\n    mdm._last_hb_mono = now - 120.0\n    restarted: list[bool] = []\n    monkeypatch.setattr(market_hours, "is_market_open", lambda: True)\n    monkeypatch.setattr(mdm, "_is_ws_healthy", lambda: False)\n    monkeypatch.setattr(mdm, "_monitor_spot_ws_health", lambda: None)\n    monkeypatch.setattr(\n        mdm, "_trigger_zombie_ws_restart", lambda: restarted.append(True)\n    )\n\n    mdm._check_zombie_ticks()\n\n    assert restarted == [True]\n''',
)

with Path(test_path).open("a") as handle:
    handle.write(
        '''\n\ndef test_symbol_recovery_attempts_are_cooldown_bounded(monkeypatch):\n    from nifty_scalper_bot.utils import market_hours\n\n    mdm = MarketDataManager(kite=None)\n    _wire_symbols(mdm)\n    stale = "NFO:NIFTY26JUN24000CE"\n    now = time.monotonic()\n    required = mdm._required_live_symbols()\n    mdm._symbols_with_tick.update(required)\n    for sym in required:\n        mdm._last_valid_live_tick_mono[sym] = now\n    mdm._last_valid_live_tick_mono[stale] = now - 120.0\n    mdm._zombie_tick_threshold_sec = 60.0\n    mdm._last_hb_mono = now\n    mdm._symbol_recovery_cooldown_s = 30.0\n    requests: list[str] = []\n    monkeypatch.setattr(market_hours, "is_market_open", lambda: True)\n    monkeypatch.setattr(mdm, "_is_ws_healthy", lambda: True)\n    monkeypatch.setattr(mdm, "_monitor_spot_ws_health", lambda: None)\n    monkeypatch.setattr(\n        mdm,\n        "request_fallback_refresh",\n        lambda symbol, reason: requests.append(symbol) or True,\n    )\n    monkeypatch.setattr(\n        mdm,\n        "_trigger_zombie_ws_restart",\n        lambda: pytest.fail("healthy transport must not restart globally"),\n    )\n\n    for _ in range(20):\n        mdm._check_zombie_ticks()\n\n    assert requests == [stale]\n\n\ndef test_trading_feed_health_exposes_required_symbol_recovery():\n    mdm = MarketDataManager(kite=None)\n    _wire_symbols(mdm)\n    mdm.set_readiness_requirements(\n        spot_symbol="NSE:NIFTY",\n        futures_symbol="NFO:NIFTY26JUNFUT",\n        atm_ce_symbol="NFO:NIFTY26JUN24000CE",\n        atm_pe_symbol="NFO:NIFTY26JUN24000PE",\n        option_symbols=[\n            "NFO:NIFTY26JUN24000CE",\n            "NFO:NIFTY26JUN24000PE",\n        ],\n    )\n\n    health = mdm.trading_feed_health(max_age_ms=60_000)\n\n    assert health["required_symbol_recovery_active"] is True\n    assert set(health["stale_required_symbols"]) == mdm._required_live_symbols()\n    assert health["trading_feed_healthy"] is False\n'''
    )

# 4. Polling installer regression without relying on an unrelated helper signature.
poll_test = Path("tests/core/test_polling_failover_runtime_installation.py")
poll_test.write_text(
    '''from __future__ import annotations\n\nfrom types import SimpleNamespace\n\nfrom nifty_scalper_bot.core.polling_failover_runtime import apply_app_patch\n\n\ndef test_apply_app_patch_replaces_unversioned_supervisor():\n    async def legacy_supervisor(*args, **kwargs):\n        return None, None\n\n    module = SimpleNamespace(\n        _polling_failover_supervisor_iteration=legacy_supervisor,\n        _polling_fallback_degraded=lambda **kwargs: False,\n    )\n\n    assert apply_app_patch(module) is True\n    installed = module._polling_failover_supervisor_iteration\n    assert installed is not legacy_supervisor\n    assert getattr(installed, "_nifty_polling_supervisor_version", None) == 2\n\n\ndef test_apply_app_patch_is_idempotent_for_versioned_supervisor():\n    async def installed_supervisor(*args, **kwargs):\n        return None, None\n\n    setattr(installed_supervisor, "_nifty_polling_supervisor_version", 2)\n    module = SimpleNamespace(\n        _polling_failover_supervisor_iteration=installed_supervisor,\n        _polling_fallback_degraded=lambda **kwargs: False,\n    )\n\n    assert apply_app_patch(module) is False\n    assert module._polling_failover_supervisor_iteration is installed_supervisor\n'''
)
